sampler sampler_smalltiled_lizard_scales;
float2 dz, dz1, uv0, uv1, uvt, uv3;
float3 flash2;
static const float2 pix = texsize.zw*2;

float GetBuf(float2 uvi)
  {float res;
  res = lerp(GetBlur1(uvi).r,GetPixel(uvi).r,0.15)-.0;
  res = pow(res,1.3)*(1+2*rand_preset.z);
  return res;}

shader_body {
uv0 = uv;

dz1.x = GetBuf(uv+pix*float2(1,0)) - GetBuf(uv+pix*float2(-1,0));
dz1.y = GetBuf(uv+pix*float2(0,1)) - GetBuf(uv+pix*float2(0,-1));
uv += dz1 * saturate(1-GetBuf(uv0))*0.3;

float rdist = GetBlur1(uv).b;
//Untergrund
ret = tex2D (sampler_smalltiled_lizard_scales,uv -3*dz1+time*0.03)
     * rdist* rand_preset.x*(rand_preset.z>0.3);

//farbiger Glanz
uv1 = uv; dz = dz1* 4*(1-rand_preset.x);
float3 refl = .1/float3 (length(uv1+dz*.6),length(uv1+dz), length(uv1+dz*2.6) ) * (0.5+GetBlur1(uv).b);
ret += refl * rdist;


ret += (GetBlur1(uv).r) * (rand_preset.y-0.2);
ret += rdist * float3 (0, 1, 3)/8;

uvt = float2(q1,q2).xy+ (tex2D(sampler_noise_hq,uv0+rand_frame.xy)-0.5)*0.07*q28*rdist;
uv3 = uv-uvt;
flash2 = q30/length (uv3+dz*0.2) *roam_sin;
ret *= 0.6+flash2*saturate(1-lum(ret)) ;

